const CODE_FENCE_PATTERN = /^```[^\n]*\n([\s\S]*?)\n?```$/u
const REGEX_LITERAL_PATTERN = /^\/(.+)\/[a-z]*$/u

export interface SearchRegexpAgentDependencies {
